S["equalizer"] = r'''
vec3 scene(vec2 uv, vec2 q) {
    // a hi-fi spectrum analyser
    float bars = 32.0;
    float b = floor(uv.x * bars);
    float f = fract(uv.x * bars);
    float h = 0.15 + 0.55 * abs(sin(time * (1.1 + hash1(b) * 1.7) + b * 0.7)) * (0.6 + 0.4 * sin(time * 0.7 + b * 0.25));
    float seg = fract(uv.y * 40.0);
    float lit = step(uv.y, h) * step(0.12, f) * step(f, 0.88) * step(0.25, seg);
    vec3 bar = uv.y > 0.6 ? c4.rgb : uv.y > 0.4 ? c2.rgb : c1.rgb;
    float peak = step(abs(uv.y - h - 0.03), 0.008) * step(0.12, f) * step(f, 0.88);
    vec3 col = c3.rgb * 0.8 + c1.rgb * 0.08 * step(0.25, seg) * step(0.12, f) * step(f, 0.88);
    return col + lit * bar + peak * c4.rgb;
}'''
S["galaxy"] = r'''
vec3 scene(vec2 uv, vec2 q) {
    // a spiral galaxy turning in deep space
    float r = length(q);
    float a = atan(q.y, q.x);
    float arms = sin(2.0 * a - log(r + 0.01) * 4.0 + time * 0.25);
    float dens = smoothstep(0.2, 1.0, arms) * exp(-r * 2.2);
    float dust = fbm(vec2(a * 2.0 + time * 0.05, r * 8.0) + q * 3.0);
    vec3 col = c3.rgb * 0.6;
    col += mix(c1.rgb, c2.rgb, dust) * dens * 1.6;
    col += c4.rgb * exp(-r * 14.0) * 0.9;
    col += step(0.997, hash(floor(uv * res / 2.0))) * c4.rgb * 0.8;
    return col;
}'''
S["kaleido"] = r'''
vec3 scene(vec2 uv, vec2 q) {
    // kaleidoscope: six mirrored slices of drifting colour
    float a = atan(q.y, q.x), r = length(q);
    float seg = 6.2832 / 6.0;
    a = mod(a + time * 0.05, seg);
    a = abs(a - seg * 0.5);
    vec2 p = vec2(cos(a), sin(a)) * r;
    float v = fbm(p * 3.0 + vec2(time * 0.12, -time * 0.08));
    float w = fbm(p * 6.0 - vec2(time * 0.07, 0.0) + v);
    return pal(v + w * 0.5 + time * 0.02);
}'''
S["ocean"] = r'''
vec3 scene(vec2 uv, vec2 q) {
    // sun setting over a calm sea, its reflection shimmering
    float hz = 0.45;
    vec3 col;
    if (uv.y > hz) {
        float t = (uv.y - hz) / (1.0 - hz);
        col = mix(c2.rgb, c3.rgb, pow(t, 0.6));
        float r = length(q - vec2(0.0, hz - 0.5 + 0.08));
        col = mix(col, c4.rgb, smoothstep(0.16, 0.15, r));
        col += c2.rgb * 0.25 * (1.0 - smoothstep(0.15, 0.6, r));
        float cl = fbm(vec2(uv.x * 3.0 + time * 0.01, uv.y * 12.0));
        col = mix(col, c1.rgb * 0.8, smoothstep(0.6, 0.75, cl) * t * 0.6);
    } else {
        float d = hz - uv.y;
        col = mix(c1.rgb * 0.7, c3.rgb, smoothstep(0.0, 0.45, d));
        float wave = sin(uv.x * 60.0 / (d + 0.05) * 0.05 + time * 1.5 + sin(uv.y * 200.0 / (d + 0.2) * 0.1)) ;
        float glint = smoothstep(0.75, 1.0, wave) * smoothstep(0.18 + d * 0.6, 0.0, abs(q.x));
        float stripe = step(0.5, fract(d * 40.0 / (d + 0.08) * 0.3 - time * 0.2));
        col = mix(col, c4.rgb, glint * 0.9);
        col = mix(col, c2.rgb, stripe * 0.08);
    }
    return col;
}'''
S["pattern"] = r'''
vec3 scene(vec2 uv, vec2 q) {
    // the tiled desktop patterns of the 90s, sliding diagonally and changing every few seconds
    vec2 p = uv * res / 4.0 + vec2(time * 6.0, -time * 4.0);
    vec2 id = floor(p / 8.0);
    vec2 f = mod(floor(p), 8.0);
    float k = mod(floor(time / 6.0), 5.0);
    float on;
    if (k < 1.0) on = step(abs(f.x - f.y), 0.5) + step(abs(f.x + f.y - 7.0), 0.5);       // diamonds
    else if (k < 2.0) on = step(f.y, 0.5) + step(f.x, 0.5) * step(mod(id.y, 2.0), 0.5)      // bricks
                     + step(abs(f.x - 4.0), 0.5) * step(0.5, mod(id.y, 2.0));
    else if (k < 3.0) on = step(mod(f.x + f.y, 4.0), 0.5);                                   // weave
    else if (k < 4.0) on = step(length(f - 3.5), 2.2) - step(length(f - 3.5), 1.2);          // rings
    else on = step(mod(f.x, 4.0), 1.5) * step(mod(f.y, 4.0), 1.5);                            // grid dots
    vec3 bg = mix(c1.rgb, c3.rgb, 0.35);
    return mix(bg, c2.rgb, clamp(on, 0.0, 1.0));
}'''

os.makedirs("src", exist_ok=True)
for name, body in S.items():
    with open("src/%s.frag" % name, "w") as f:
        f.write(HEADER + body + FOOTER)
print(len(S), "scenes:", " ".join(S))

# ---------------------------------------------------------------- effects over a picture
# Transparent overlays (snow, stars…) drawn on top of an ordinary wallpaper. c1 = the effect's
# colour, c2 = the accent. `density` 0.25…2 scales how many particles there are.
FX_HEADER = r'''#version 440
// Bevel wallpaper effect — generated by live/build.py. Drawn over a picture, so it has alpha.
layout(location = 0) in vec2 qt_TexCoord0;
layout(location = 0) out vec4 fragColor;
layout(std140, binding = 0) uniform buf {
    mat4 qt_Matrix;
    float qt_Opacity;
    float time;
    float pixel;
    float density;
    vec2 res;
    vec4 c1;
    vec4 c2;
};
float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
// one particle per grid cell (if the cell gets one): where it sits inside the cell, and its random number
vec3 cellp(vec2 g, float seed) {
    vec2 id = floor(g);
    float h = hash(id + seed);
    return vec3(vec2(hash(id + seed + 7.13), hash(id + seed + 3.71)) * 0.6 + 0.2, h);
}
'''
FX_FOOTER = r'''
void main() {
    float px = max(1.0, pixel);
    vec2 cell = floor(qt_TexCoord0 * res / px);
    vec2 p = (cell + 0.5) * px;               // chunky pixels
    vec2 uv = p / res;
    uv.y = 1.0 - uv.y;                         // y up
    vec4 e = effect(uv, (uv - 0.5) * vec2(res.x / res.y, 1.0));
    float a = clamp(e.a, 0.0, 1.0);
    fragColor = vec4(clamp(e.rgb, 0.0, 1.0) * a, a) * qt_Opacity;
}
'''
FX = {}
FX["snow"] = r'''
vec4 effect(vec2 uv, vec2 q) {
    float a = 0.0;
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float s = 0.07 - fi * 0.015;                     // far layers: smaller, slower, denser
        vec2 g = q / s + vec2(0.0, time * (0.9 - fi * 0.22) / (s * 10.0));
        g.x += sin(time * 0.6 + floor(g.y) * 1.7 + fi) * 0.35;
        vec3 c = cellp(g, fi * 11.0);
        if (c.z > 0.45 * density) continue;
        float d = length(fract(g) - c.xy) * s;
        a = max(a, smoothstep(0.0045 - fi * 0.001, 0.002 - fi * 0.0006, d) * (1.0 - fi * 0.25));
    }
    return vec4(c1.rgb, a);
}'''
FX["stars"] = r'''
vec4 effect(vec2 uv, vec2 q) {
    float a = 0.0;
    // twinkling stars, more of them higher up
    vec2 g = q / 0.025;
    vec3 c = cellp(g, 1.0);
    if (c.z < 0.22 * density * (0.4 + uv.y)) {
        float tw = pow(0.5 + 0.5 * sin(time * (1.0 + c.z * 9.0) + c.z * 60.0), 3.0);
        float d = length(fract(g) - c.xy) * 0.025;
        a = smoothstep(0.0034, 0.0012, d) * (0.35 + 0.65 * tw);
    }
    // now and then a shooting star
    float k = floor(time / 5.0);
    float t = fract(time / 5.0) * 5.0;
    if (t < 0.8 && hash(vec2(k, 2.0)) < 0.7 * density) {
        vec2 st = vec2(hash(vec2(k, 3.0)) - 0.2, 0.25 + 0.2 * hash(vec2(k, 4.0)));
        vec2 dir = normalize(vec2(1.0, -0.45));
        vec2 head = st + dir * t * 0.9;
        vec2 rel = q - head;
        float along = dot(rel, -dir), across = abs(dot(rel, vec2(-dir.y, dir.x)));
        float tail = step(0.0, along) * smoothstep(0.18, 0.0, along) * smoothstep(0.003, 0.0, across);
        a = max(a, tail * (1.0 - t / 0.8));
    }
    return vec4(c1.rgb, a);
}'''
FX["rain"] = r'''
vec4 effect(vec2 uv, vec2 q) {
    float a = 0.0;
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        vec2 r = vec2(q.x + q.y * 0.18, q.y);                       // a little wind
        vec2 s = vec2(0.012 + fi * 0.006, 0.09 - fi * 0.02);
        vec2 g = r / s + vec2(0.0, time * (2.4 - fi * 0.6) / s.y);
        vec3 c = cellp(g, fi * 5.0);
        if (c.z > 0.35 * density) continue;
        vec2 f = fract(g) - vec2(c.x, 0.5);
        float streak = smoothstep(0.18, 0.0, abs(f.x)) * smoothstep(0.5, 0.0, abs(f.y));
        a = max(a, streak * (0.55 - fi * 0.2));
    }
    return vec4(c1.rgb, a);
}'''
FX["fireflies"] = r'''
vec4 effect(vec2 uv, vec2 q) {
    float a = 0.0;
    vec2 g = q / 0.08;
    vec2 id = floor(g);
    for (int dy = -1; dy <= 1; dy++)
    for (int dx = -1; dx <= 1; dx++) {
        vec2 n = id + vec2(float(dx), float(dy));
        float h = hash(n + 9.0);
        if (h > 0.55 * density) continue;
        vec2 pos = n + 0.5 + 0.45 * vec2(sin(time * (0.3 + h) + h * 30.0), cos(time * (0.25 + h * 0.7) + h * 17.0));
        float d = length(g - pos) * 0.08;
        float blink = 0.15 + 0.85 * smoothstep(-0.2, 1.0, sin(time * (0.8 + h) + h * 50.0));
        a = max(a, (smoothstep(0.0055, 0.0025, d) + smoothstep(0.025, 0.0, d) * 0.45) * blink * (0.6 + 0.4 * (1.0 - uv.y)));
    }
    return vec4(mix(c1.rgb, vec3(1.0, 0.95, 0.5), 0.5), a);
}'''
FX["leaves"] = r'''
vec4 effect(vec2 uv, vec2 q) {
    vec4 o = vec4(0.0);
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float s = 0.11 - fi * 0.03;
        vec2 g = q / s + vec2(time * 0.12 / s, time * (0.22 - fi * 0.05) / s);
        g.x += sin(time * 0.9 + floor(g.y) * 2.1) * 0.25;
        vec3 c = cellp(g, 20.0 + fi);
        if (c.z > 0.4 * density) continue;
        vec2 f = (fract(g) - c.xy) * s;
        float ang = time * (1.0 + c.z * 2.0) + c.z * 20.0;
        f = mat2(cos(ang), -sin(ang), sin(ang), cos(ang)) * f;
        float sz = 0.009 - fi * 0.002;
        float leaf = step(length(f * vec2(1.0, 2.2)), sz);
        float k = fract(c.z * 7.3);
        vec3 col = k < 0.33 ? vec3(0.80, 0.30, 0.10) : (k < 0.66 ? vec3(0.90, 0.60, 0.12) : vec3(0.62, 0.20, 0.12));
        if (leaf > 0.5) o = vec4(mix(col, c2.rgb, 0.15), 0.95 - fi * 0.2);
    }
    return o;
}'''
FX["petals"] = r'''
vec4 effect(vec2 uv, vec2 q) {
    vec4 o = vec4(0.0);
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float s = 0.09 - fi * 0.02;
        vec2 g = q / s + vec2(time * (0.18 - fi * 0.04) / s, time * (0.14 - fi * 0.03) / s);
        g.y += sin(time * 1.1 + floor(g.x) * 1.3) * 0.3;
        vec3 c = cellp(g, 40.0 + fi);
        if (c.z > 0.4 * density) continue;
        vec2 f = (fract(g) - c.xy) * s;
        float ang = time * 1.5 + c.z * 30.0;
        f = mat2(cos(ang), -sin(ang), sin(ang), cos(ang)) * f;
        float sz = 0.0065 - fi * 0.0015;
        if (length(f * vec2(1.0, 1.7)) < sz) o = vec4(mix(vec3(1.0, 0.75, 0.85), c1.rgb, 0.2) * (1.0 - fi * 0.12), 0.95 - fi * 0.2);
    }
    return o;
}'''
FX["bubbles"] = r'''
vec4 effect(vec2 uv, vec2 q) {
    float a = 0.0;
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float s = 0.12 - fi * 0.04;
        vec2 g = q / s - vec2(0.0, time * (0.12 - fi * 0.03) / s);
        g.x += sin(time * 0.8 + floor(g.y) * 1.9) * 0.2;
        vec3 c = cellp(g, 60.0 + fi);
        if (c.z > 0.3 * density) continue;
        float r = (0.012 + c.z * 0.02) * (1.0 - fi * 0.3);
        float d = length((fract(g) - c.xy) * s);
        float ring = smoothstep(0.0025, 0.0, abs(d - r));
        float shine = smoothstep(r * 0.35, 0.0, length((fract(g) - c.xy) * s + vec2(r * 0.4, -r * 0.4)));
        a = max(a, max(ring * 0.7, shine * 0.8) * (1.0 - fi * 0.3));
    }
    return vec4(c1.rgb, a);
}'''
FX["embers"] = r'''
vec4 effect(vec2 uv, vec2 q) {
    float a = 0.0;
    vec3 col = vec3(0.0);
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float s = 0.06 - fi * 0.015;
        vec2 g = q / s - vec2(0.0, time * (0.3 - fi * 0.08) / s);
        g.x += sin(time * 1.7 + floor(g.y) * 2.3) * 0.3;
        vec3 c = cellp(g, 80.0 + fi);
        if (c.z > 0.3 * density) continue;
        float d = length((fract(g) - c.xy) * s);
        float life = smoothstep(0.0, 0.6, 1.0 - uv.y) ;
        float flick = 0.6 + 0.4 * sin(time * 9.0 + c.z * 40.0);
        float e = smoothstep(0.005, 0.002, d) * life * flick;
        if (e > a) { a = e; col = mix(vec3(1.0, 0.45, 0.1), vec3(1.0, 0.85, 0.3), c.z); }
    }
    return vec4(mix(col, c2.rgb, 0.15), a);
}'''
FX["confetti"] = r'''
vec4 effect(vec2 uv, vec2 q) {
    vec4 o = vec4(0.0);
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float s = 0.08 - fi * 0.02;
        vec2 g = q / s + vec2(0.0, time * (0.35 - fi * 0.08) / s);
        g.x += sin(time * 1.4 + floor(g.y) * 2.7) * 0.3;
        vec3 c = cellp(g, 100.0 + fi);
        if (c.z > 0.35 * density) continue;
        vec2 f = (fract(g) - c.xy) * s;
        float ang = time * 3.0 + c.z * 40.0;
        f = mat2(cos(ang), -sin(ang), sin(ang), cos(ang)) * f;
        float w = 0.006 * abs(cos(time * 4.0 + c.z * 20.0)) + 0.0015;   // spinning: it narrows and widens
        if (abs(f.x) < w && abs(f.y) < 0.004) {
            float k = fract(c.z * 13.7);
            vec3 col = k < 0.2 ? vec3(0.95, 0.3, 0.3) : k < 0.4 ? vec3(0.3, 0.7, 1.0) : k < 0.6 ? vec3(1.0, 0.85, 0.2)
                     : k < 0.8 ? vec3(0.4, 0.9, 0.5) : c2.rgb;
            o = vec4(col, 1.0 - fi * 0.2);
        }
    }
    return o;
}'''
